trait Handler {
    fn handle(&mut self, req: &Request) -> Option<Response>;
}

struct Auth { next: Option<Box<dyn Handler>> }
impl Handler for Auth {
    fn handle(&mut self, req: &Request) -> Option<Response> {
        if req.header("x-api-key").is_none() { return Some(Response::status(401)); }
        self.next.as_mut().and_then(|h| h.handle(req))    // forward
    }
}

